private static int indexOf(final int calendarUnit) {
        int i;
        for(i = 0; i <CALENDAR_UNITS.length; i++) {
            if (calendarUnit == CALENDAR_UNITS[i]) {
                return i;
            }
        }
        return 0;
    }

